changes=git('diff','--name-status','--no-renames',base,head).splitlines()
assert all(line.split('\t')[0] in ['A','M'] for line in changes),'Source deletion or rename denied'
assert {line.split('\t')[1] for line in changes}==set(allowed),'Outside exact cPanel POS operator scope'
for path,items in blocks.items():
 current=source(head,path)
 for addition in items:
  assert addition in current,'Missing exact operator successor condition '+path
  current=current.replace(addition,'',1)
 assert current==source(base,path),'Historical executable workflow changed '+path
for path,digest in proof.items():
 assert hashlib.sha256(source(head,path).encode()).hexdigest()==digest,'Operator or verification differs from exact source '+path
assert not git('diff','--name-only',base,head,'--','apps','ops','release'),'Certified application, dependencies, migration history or deployment state changed'
for path in ['tools/production/cpanel/update-oneqaydev-control-plane.php','tools/production/cpanel/install-oneqaydev-control-plane.php']:
 assert source(head,path)==source(base,path),'Historical operator changed'
assert source(head,'tools/production/cpanel/release-retention.php')==source(base,'tools/production/cpanel/release-retention.php'),'Retention helper changed'
assert len(git('ls-tree','--name-only',head+':apps/web/database/migrations').splitlines())==27
print('CPANEL_POS_WORKER_LOCK_SOURCE_ENVELOPE_PASS')
